#include<bits/stdc++.h>

using namespace std;

int main(void) {
	int n, k;
	int s = 0;
	cin >> n >> k;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= k; j++) {
			s += (100 * i + j);
		}
	}
	cout << s << endl;
	return 0;
}

